// Ingestion rule: reject any endpoint matching /\{[A-Za-z_][A-Za-z0-9_]*\}/

{
  "type": "https://eips.ethereum.org/EIPS/eip-8004#service.mcp",
  "name": "@quackai/q402-mcp",
  "version": "0.11.15",
  "transport": "stdio",
  "registry": {
    "npm": "https://www.npmjs.com/package/@quackai/q402-mcp",
    "anthropicMcp": "https://registry.modelcontextprotocol.io"
  },
  "install": {
    "npx": "npx -y @quackai/q402-mcp@latest",
    "claudeCode": "claude mcp add q402 -- npx -y @quackai/q402-mcp@latest"
  },
  "tools": [
    { "name": "q402_pay",       "description": "Execute a single gasless stablecoin payment." },
    { "name": "q402_batch_pay", "description": "Execute many payments in one relayed call." },
    { "name": "q402_balance",   "description": "Read stablecoin holdings for the agent or user." },
    { "name": "q402_quote",     "description": "Price a payment before ..." }
  ]
}

// transport:"stdio" => NOT remotely invocable. POST /api/mcp/info with a
// JSON-RPC initialize returns HTTP 405 Method Not Allowed. GET returns this doc.
